affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culinary":"destination","culture":"destination","romance":"destination"},"commission_lane":["DMC","affiliate","school"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sumapaz páramo trek","tier":"premier","source":"https://www.lonelyplanet.com/articles/day-hikes-bogota-colombia","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the world''s largest páramo ecosystem, south of Bogotá; high-altitude moorland trekking, guided-only","si":"adventure","blurb":"the world''s largest páramo ecosystem, south of Bogotá; high-altitude moorland trekking, guided-only","when":"Dec–Mar  and Jul–Aug","commission":"GEA DMC / licensed guide (guided-only)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culinary":"destination","culture":"destination","romance":"destination"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Paloquemao market + coffee","tier":"essential","source":"https://theabroadguide.com/la-candelaria-mount-monserrate-and-the-gold-museum-in-one-day-in-bogota/","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Bogotá''s great produce, flower and food market; early-morning fruit tastings and Colombian-coffee sourcing, a food-tour anchor","si":"culinary","blurb":"Bogotá''s great produce, flower and food market; early-morning fruit tastings and Colombian-coffee sourcing, a food-tour anchor","when":"Dec–Mar  and Jul–Aug","commission":"food-tour affiliate + DMC","wells":["eat","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary"],"shelf_fit":{"adventure":"destination","culinary":"primary","culture":"destination","romance":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Andrés Carne de Res (Chía)","tier":"premier","source":"https://www.tripadvisor.com/Restaurant_Review-g815502-d939879-Reviews-Andres_Carne_De_Res_Chia-Chia_Cundinamarca_Department.html","timing":"Dec–Mar  and Jul–Aug","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the legendary maximalist restaurant ~40–60 min north of Bogotá — a labyrinth of over-the-top décor, live music and improv actors","si":"culinary","blurb":"the legendary maximalist restaurant ~40–60 min north of Bogotá — a labyrinth of over-the-top décor, live music and improv actors","when":"Dec–Mar  and Jul–Aug","commission":"DMC dining + vetted transport","wells":["eat"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary"],"shelf_fit":{"adventure":"destination","culinary":"primary","culture":"destination","romance":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the most romantic thing to do in Bogotá?","a":"Ride the funicular or cable car up Monserrate at dusk for dinner at the summit restaurant, with the whole plateau of light beneath you — the city''s signature romance run. The ridge rises to 3,152 m (10,341 ft), and the Basilica crowns the summit.","source":"kittiaroundtheworld.com, 2026-07-07","si_tag":"romance","accessed":"2026-07-07"},{"q":"Can you go hiking near Bogotá?","a":"Yes — Andean páramo day-hikes start on the city''s doorstep and run guided. Chingaza páramo climbs from 2,600 to 4,000 m through frailejón moorland and glacial Siecha/Buitrago lagoons, while Suesca, about 1 hour north, is Colombia''s premier rock-climbing crag. Guided entry is the norm for the páramos.","source":"mytriptocolombia.com, 2026-07-07","si_tag":"adventure","accessed":"2026-07-07"},{"q":"What are the must-see museums and sights in Bogotá?","a":"The Gold Museum (Museo del Oro) is the headline — ~55,000 pre-Columbian gold pieces, including the Muisca raft of the El Dorado legend, and free on Sundays — alongside the Botero Museum and colonial La Candelaria. The core clusters in and above the historic centre.","source":"viator.com, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"},{"q":"Where should you eat and drink around Bogotá?","a":"Andrés Carne de Res in Chía is the marquee night out — ranked #2 of 139 restaurants in Chía, a labyrinth of over-the-top décor, live music and improv actors, about 40–60 min north of the city. In town, Zona G is Bogotá''s dense \"gourmet zone.\"","source":"tripadvisor.com, 2026-07-07","si_tag":"culinary","accessed":"2026-07-07"},{"q":"What''s the real risk to plan for in Bogotá?","a":"Scopolamine (\"devil''s breath\" / burundanga) drugging is the headline traveler risk — a colourless, tasteless sedative used to rob or assault. Bogotá police recorded 1,409 cases in 2023 (+16% year-on-year), concentrated in Chapinero, Teusaquillo and Santa Fe, often via dating apps and offered drinks. Never accept drinks or tabs from strangers.","source":"thecitypaperbogota.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"},{"q":"Is walking up Monserrate dangerous?","a":"Walk the Monserrate pilgrimage trail only in daylight and in groups — robberies have been reported on the path — or take the funicular or cable car instead. The summit stands at 3,152 m, so pace yourself for the altitude.","source":"kittiaroundtheworld.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"}],"seo":{"meta_title":"Bogotá & The Andes, Colombia — Gold Museum, Monserrate, Zipaquirá & Villa de Leyva | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-CO","local_keywords":["qué hacer en Bogotá","Catedral de Sal Zipaquirá","Museo del Oro","Villa de Leyva","Monserrate Bogotá","hoteles de lujo Bogotá"],"hreflang":["en","es-CO"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"O