including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Jul-Nov (best visibility, bull-shark aggregation)","shoulder":"Apr-Jun, late fall","green":"Dec-Feb (coolest water, wind days)","out_of_season_fill":"winter dive-and-stay packages; East Cape / Los Cabos day-trip combos","fire_date":"late spring for summer-fall dive peak; Los Cabos winter high season for day-trip capture","event_peaks":["US/Canada summer holidays","Los Cabos Dec-Apr high-season spillover"],"booking_lead":"2-4 months (capped dive slots + tiny bed inventory)"},"jewels":[{"status":"live","tier":"essential","commission":"operator agreement","name":"Pulmo reef recovery dive","si":"expedition","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","expedition"],"shelf_fit":{"diveglobal":"evidenced","expedition":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"premier","commission":"operator agreement","name":"Bull-shark aggregation dive","si":"expedition","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","expedition"],"shelf_fit":{"diveglobal":"evidenced","expedition":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"essential","commission":"operator + DMC","name":"Protected-reef snorkel","si":"expedition","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","expedition"],"shelf_fit":{"diveglobal":"evidenced","expedition":"primary"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"premier","commission":"operator agreement","name":"Sea-lion / offshore pinnacle dives","si":"expedition","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''operator agreement''","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"future","tier":"premier","commission":"operator; stay direct","name":"Multi-day Cabo Pulmo dive-and-stay","si":"diveglobal","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","expedition":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Is Cabo Pulmo worth diving, and what will I see?","a":"Yes — it is arguably the Sea of Cortez''s best dive, because protection worked: total fish biomass rebounded 463% by 2009 on the Gulf''s only living hard-coral reef. Expect schooling jacks, groupers and rays, and in warm summer–fall water a bull-shark aggregation.","source":"ocean.si.edu / divearoo.com, 2026-07-04","si_tag":"expedition","accessed":"2026-07-04"},{"q":"Do I need to be certified, and can non-divers go?","a":"You dive within your card with a mandatory park guide (max 6 divers each), and non-divers can snorkel the same no-take reef. The rules are strict — no gloves, no touching, licensed pangas only — and enforced; break them and you can be pulled from the water.","source":"mexicotraveladventure.com, 2026-07-04","si_tag":"diveglobal","accessed":"2026-07-04"},{"q":"Can couples make a romantic escape of Cabo Pulmo?","a":"Only if \"romantic\" means off-grid and simple — there is no resort or spa layer. Lodging is solar eco-cabañas and a tiny villa cluster (~5 villas), which suits low-key couples; anyone wanting branded luxury bases in Los Cabos or the East Cape and day-trips in.","source":"sallysees.com / cabopulmo.com, 2026-07-04","si_tag":"romance","accessed":"2026-07-04"},{"q":"Is diving here dangerous — what''s the real risk?","a":"The gatekeeper is medevac distance, not the diving itself. Cabo Pulmo is off-grid with no chamber or hospital in the village; the nearest recompression chamber and trauma care are ~2–3 hours away in Los Cabos, so dive conservatively, carry DAN cover, and observe 18–24 h no-fly before an SJD departure.","source":"sssnetwork.com / dan.org, 2026-07-04","si_tag":"safety","accessed":"2026-07-04"}],"seo":{"meta_title":"Cabo Pulmo Diving — Sea of Cortez No-Take Reef | TravelWell.World","meta_description":"Dive Cabo Pulmo, the most-recovered no-take marine reserve in the Sea of Cortez. Guided park dives, no-touch rules, eco-cabaña stays, Los Cabos gateway logistics.","long_tail":["best time to dive Cabo Pulmo","Cabo Pulmo bull shark season","how to get to Cabo Pulmo from Los Cabos","Cabo Pulmo eco cabañas"],"search_language":"es-MX","local_keywords":["buceo Cabo Pulmo","Parque Nacional Cabo Pulmo","arrecife de coral Mar de Cortes","snorkel Cabo Pulmo","reserva marina sin pesca","cabanas ecologicas Cabo Pulmo"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"primary_keyword":["Cabo Pulmo diving","Cabo Pulmo National Park","Cabo Pulmo snorkeling","Sea of Cortez reef"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"what":"Four Seasons Los Cabos at Costa Palmas / Amanvari (East Cape, Los Cabos) as luxury base for a Cabo Pulmo dive charter","why_ultra":"largest swimmable beach + only private marina in Los Cabos; Amanvari is first Aman in Mexico (spring 2026)","earning":"on application / via host-Virtuoso","virtuoso_value_add":"resort credit, upgrade, breakfast; private guide for Pulmo run","mor":"resale via host-Virtuoso only; Cabo Pulmo itself is NOT an ultra stay — nearest ultra is Los Cabos"}],"source_verified":"2026-07-04","hero":{"query":"Cabo Pulmo, Mexico"},"geo":{"lat":23.4433,"lng":-109.4283},"orbit":[{"id":"balandra-beach-mexico","jewels":5,"si":["tropical","family","romance"]},{"id":"cabo-san-lucas-mexico","jewels":6,"si":["liveaboard","expedition","ocean","ultra"]},{"id":"east-cape-mexico","jewels":7,"si":["romance","expedition","diveglobal","ocean"]},{"id":"espiritu-santo-island-mexico","jewels":5,"si":["expedition","ocean"]},{"id":"la-paz-mexico","jewels":6,"si":["expedition","tropical","diveglobal"]},{"id":"loreto-mexico","jewels":7,"si":["expedition","tropical","diveglo