rro liveaboard Nov-Jun; NYE + Spring Break premium","shoulder":"May and October (October carries Bisbee''s crowd)","green":"Jul-Sep hot/humid, Pacific hurricane/chubasco season Jun-Nov (peak Sep-Oct); Socorro closed","booking_lead":"Socorro liveaboards 6-12+ months ahead; Bisbee''s-week lodging + charters months ahead; NYE/Spring-Break villas + ultra suites months ahead","off_season_specials":"green-summer value (lowest rates, warm sea, dorado/tuna fishing) to price-sensitive couples/families + mandatory hurricane trip insurance","event_peaks":["Bisbee''s Black & Blue Oct 19-24 2026 ($11.5M+ purse)","Christmas/NYE premium","US Spring Break (Mar)","whale season Dec 15-Apr 15"],"fire_date":"Socorro campaign 9-12 months out; whale-season push Aug-Oct; Bisbee''s/sportfishing micro-campaign spring-summer; green-value push May-Jun"},"jewels":[{"name":"Socorro/Revillagigedo giant-manta liveaboard","status":"live","hook":"giant Pacific mantas approach + stay; up to 10 shark species, whale sharks, humpbacks","bookable_category":"liveaboard","tier":"premier","source":"https://nautilusliveaboards.com/socorro/","si":"liveaboard","blurb":"giant Pacific mantas approach + stay; up to 10 shark species, whale sharks, humpbacks","commission":"Aggressor/liveaboard reseller = Commissioned Agent on application (TCI moat)","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["liveaboard"],"shelf_fit":{"expedition":"destination","liveaboard":"primary","ocean":"destination","privatejet":"destination","ultra":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Roca Partida (Socorro site)","status":"live","hook":"isolated open-ocean pinnacle, silvertips + Galapagos sharks in the current","bookable_category":"liveaboard itinerary","tier":"premier","source":"https://www.bluewaterdivetravel.com/destination/socorro-island-diving","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"isolated open-ocean pinnacle, silvertips + Galapagos sharks in the current","when":"Nov-Apr","commission":"liveaboard reseller = Commissioned Agent on application","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — si (unambiguous spend type)","si_all":["liveaboard"],"shelf_fit":{"expedition":"destination","liveaboard":"primary","ocean":"destination","privatejet":"destination","ultra":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Gray + humpback whale-watching","status":"live","hook":"humpback breaching/mating + gray whale calves","bookable_category":"whale-watch tour","tier":"essential","source":"https://www.visitloscabos.travel/blog/post/whale-watching-in-los-cabos-2025-the-ultimate-guide-to-an-unforgettable-season/","si":"expedition","blurb":"humpback breaching/mating + gray whale calves","commission":"DMC + Viator/GYG affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","liveaboard":"destination","ocean":"destination","privatejet":"destination","ultra":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Bisbee''s Black & Blue marlin sportfishing","status":"future","hook":"world''s richest billfish tournament; Marlin Capital of the World","bookable_category":"sportfishing charter","tier":"comfort","source":"https://bisbees.com/tournaments/bisbees-black-blue","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"world''s richest billfish tournament; Marlin Capital of the World","when":"Nov-Apr","commission":"charter/DMC commission on application","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ocean"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","ocean":"primary","privatejet":"destination","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Land''s End / El Arco + Pelican Rock snorkel","status":"future","hook":"iconic granite arch + easy snorkel at the peninsula tip","bookable_category":"boat/snorkel tour","tier":"essential","source":"https://www.cabovillas.com/yacht-tours","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"iconic granite arch + easy snorkel at the peninsula tip","when":"Nov-Apr","commission":"Viator/GYG affiliate + DMC","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ocean"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","ocean":"primary","privatejet":"destination","ultra":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Superyacht + private-jet charter","status":"future","hook":"jet-to-yacht for the ultra client","bookable_category":"charter","tier":"ultra","source":"https://www.cabovillas.com/jet-charters","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ultra","blurb":"jet-to-yacht for the ultra client","when":"Nov-Apr","commission":"charter/DMC commission on application","wells":["fly"],"wells_basis":"derived from name/blurb/hook","si_all":["privatejet","ultra"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","ocean":"destination","privatejet":"evidenced","ultra":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Luxury","si_map_basis":"normalised from free text ''Luxury'' by gen_normalise_jewel_si","si_basis":"this jewel NAMES a privatejet product; gen_cat2_from_named_products"}],"faq":[{"q":"When can I dive Socorro from Cabo, and what will I see?","a":"Socorro runs by liveaboard only, roughly November–June, on a ~24-hour crossing from Cabo — there is no day-boat option. The draw is giant Pacific mantas that approach and stay through whole dives, up to 10 shark species, dolphins, whale sharks (Nov–Dec) and humpbacks (Jan–Mar). Book berths 6–12+ months out.","source":"bluewaterdivetravel.com, 2026-07-04","si_tag":"liveaboard","accessed":"2026-07-04"},{"q":"When is whale season in Cabo?","a":"December 15 to April 15, with peak sightings January–March. Humpbacks breach and mate while gray whales pass with newborn calves, all on boat-based tours out of Cabo.","source":"visitloscabos.travel, 2026-07-04","si_tag":"expedition","accessed":"2026-07-04"},{"q":"When is Bisbee''s, and is Cabo really the \"Marlin Capital\"?","a":"Bisbee''s Black & Blue runs the third week of October — Oct 19–24 in 2026 — with a purse topping $11.5 million, and Cabo backs the \"Marlin Capital\" tag with year-round blue and black marlin, dorado and tuna. Tournament-week lodging and charters sell out months ahead.","source":"bisbees.com, 2026-07-04","si_tag":"ocean","accessed":"2026-07-04"},{"q":"Is Cabo good for a honeymoon, and where''s the top end?","a":"Yes — it is one of North America''s densest ultra clusters, with multiple Forbes Five-Star flags. The honeymoon flagships are Las Ventanas al Paraíso (Rosewood) and One&Only Palmilla; Waldorf Astoria Pedregal, Montage and Chileno Bay sit alongside on the corridor''s rare swimmable coves.","source":"forbes.com, 2026-07-04","si_tag":"romance","accessed":"2026-07-04"},{"q":"Is diving Socorro dangerous?","a":"It is advanced, remote diving — manageable with discipline. Socorro has strong currents, deep pelagic sites and no chamber at the archipelago; a hit means a ~24-hour steam back to Cabo''s chamber. Dive within your certification, follow the boat''s conservative plan, carry DAN evacuation cover, and wait 18–24 h before flying home.","source":"bluewaterdivetravel.com / dan.org, 2026-07-04","si_tag":"safety","accessed":"2026-07-04"}],"seo":{"meta_title":"Cabo San Lucas: Socorro Liveaboards, Whales & Ultra Cabo","meta_description":"Cabo San Lucas is the port where Socorro''s giant-manta liveaboards begin - plus whale season, Bisbee''s marlin, and one of North America''s densest ultra-luxury clusters.","slug":"cabo-san-lucas-mexico","primary_keyword":"Cabo San Lucas Socorro liveaboard","long_tail":["Socorro Revillagigedo liveaboard from Cabo","Cabo whale watching season","Bisbee''s Black and Blue 2026 dates","Cabo San Lucas luxury resorts Virtuoso","giant manta ray diving Mexico"],"search_language":["en","es-MX"],"local_keywords":["buceo liveaboard Socorro desde Cabo San Lucas","avistamiento de ballenas Los Cabos","torneo de marlin Bisbee''s Black and Blue","mantarraya gigante Revillagigedo","villas de lujo en Cabo San Lucas","resorts cinco estrellas Los Cabos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"liveaboard","status":"live","note":"Socorro/Revillagigedo liveaboards depart Cabo San Lucas, ~24h crossing, Nov-Jun season"},{"si":"expedition","status":"live","note":"gray + humpback whale-watching Dec 15-Apr 15"},{"si":"ocean","status":"future"},{"si":"ultra","status":"future"}],"ultra":[{"name":"Waldorf Astoria Los Cabos Pedregal","why_ultra":"top overall Los Cabos rec; clif