  ('calakmul-mexico', '10S', 'Calakmul, Mexico', 'Mexico', 'Calakmul', 'live', 'verified', 'mountainValley', 'Campeche (Campeche City & Calakmul)', '{"culture","wildlife","expedition"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","air_access_verified":true,"access_notes":"Campeche (CPE) / Chetumal (CTM) airports + Tren Maya Xpujil station (live Dec 2024); 60–110 km jungle drive to ruins; car mandatory for final leg","remote_flag":true,"health_flags":["malaria (P. vivax, low, prophylaxis recommended for Campeche)","dengue/Zika/chikungunya (tropical, day-biting)","heat/humidity","unlit wildlife access road"],"water":"bottled/purified only","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"November–April (dry season; wildlife at waterholes, road passable)","inflection":"October (wet-season taper + Yucatán high-season pull)","fire_date":"2026-09-15 to 2026-09-22 (curve-start minus 1–2 weeks)","attach":["Campeche/Yucatán itinerary","Tren Maya circuit","Bacalar","Chetumal","Palenque"],"off_season_specials":"May–October wet season — heat, humidity, road degradation, higher vector risk"},"jewels":[{"name":"Structure II summit over the canopy + Great Plaza","tier":"comfort","source":"https://en.wikipedia.org/wiki/Calakmul","timing":"year-round","timing_type":"ALWAYS-ON","hook":"Climb the tallest pyramid at Calakmul at first light","si":"expedition","blurb":"Climb the tallest pyramid at Calakmul at first light","when":"year-round","commission":"DMC guided-climb + sunrise transfer","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary","wildlife":"destination"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Dawn howler & spider monkeys + toucans + jaguar sign","tier":"comfort","source":"http://world-heritage-datasheets.unep-wcmc.org/datasheet/output/site/ancient-maya-city-and-protected-tropical-forests-of-calakmul-campeche/","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The reserve holds Mexico''s highest jaguar density and 365+ bird species","si":"expedition","blurb":"The reserve holds Mexico''s highest jaguar density and 365+ bird species","when":"November–April","commission":"licensed wildlife-guide add-on, DMC-bundled","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''licensed wildlife-guide add-on, dmc-bund''","si_all":["expedition","wildlife"],"shelf_fit":{"culture":"destination","expedition":"primary","wildlife":"evidenced"},"commission_lane":["DMC","bundle","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Bat Cave (Volcán de los Murciélagos) dusk exodus","tier":"essential","source":"https://www.beyondtheordinary.co.uk/features/calakmul-bat-cave/","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"One of only two \"bat volcano\" spectacles on Earth","si":"expedition","blurb":"One of only two \"bat volcano\" spectacles on Earth","when":"November–April","commission":"dusk-timed guided add-on / DMC evening leg","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary","wildlife":"destination"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Birding — 350+ species","tier":"comfort","source":"http://world-heritage-datasheets.unep-wcmc.org/datasheet/output/site/ancient-maya-city-and-protected-tropical-forests-of-calakmul-campeche/","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"From ocellated turkey to keel-billed toucan to raptors over the canopy; the reserve is a top Yucatán-Peninsula birding target","si":"expedition","blurb":"From ocellated turkey to keel-billed toucan to raptors over the canopy; the reserve is a top Yucatán-Peninsula birding target","when":"November–April","commission":"specialist birding-guide day, DMC-bundled","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition","wildlife"],"shelf_fit":{"culture":"destination","expedition":"primary","wildlife":"evidenced"},"commission_lane":["DMC","bundle","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Río Bec route — Becán, Chicanná, Xpujil, Balamkú (16.8 m stucco frieze)","tier":"essential","source":"https://lostruinsoftheamericas.com/balamku/","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A corridor of Río Bec-style ruins: theatrical false towers, rounded corners, and monster-mouth doorways, all within short drives of Xpujil","si":"culture","blurb":"A corridor of Río Bec-style ruins: theatrical false towers, rounded corners, and monster-mouth doorways, all within short drives of Xpujil","when":"November–April","commission":"heritage day-loop add-on, DMC-bundled","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","wildlife":"destination"},"commission_lane":["DMC","bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Calakmul as Snake Kingdom (Kaan) capital — Tikal rivalry narrative","tier":"comfort","source":"https://en.wikipedia.org/wiki/Calakmul","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The narrative jewel: seat of the Kaan dynasty","si":"culture","blurb":"The narrative jewel: seat of the Kaan dynasty","when":"November–April","commission":"archaeologist-led interpretive guiding, DMC premium","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''archaeologist-led interpretive guiding, ''","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","wildlife":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Zoh-Laguna village nature base","tier":"essential","source":"https://riobecdreams.com/","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","when":"November–April","commission":"small-lodge stay + local guide","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","wildlife":"primary"},"commission_lane":["hotel","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tren Maya arrival (Xpujil station)","source":"https://www.mexicotravelandleisure.com/blog/maya-train-route-and-guide/","timing":"November–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The rail arrival is itself a jewel now: glide inland from Cancún/Palenque to Xpujil, then transfer to the jungle","si":"wildlife","blurb":"The rail arrival is itself a jewel now: glide inland from Cancún/Palenque to Xpujil, then transfer to the jungle","when":"November–April","commission":"rail affiliate + DMC meet-and-transfer","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","wildlife":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for at Calakmul?","a":"The drive itself. The reserve is 60–110 km of narrow, unlit jungle road past the last fuel and signal at Xpujil, with a ~30 km/h wildlife limit and no in-reserve hospital — serious trauma means a 2–4 hr evacuation to Campeche City or Chetumal. Carry evacuation-grade insurance, fuel up in Xpujil, and note that rural Campeche is a CDC malaria-prophylaxis (P. vivax) state with dengue present, so bite prevention matters.","source":"casakaan.com / wwwnc.cdc.gov, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"},{"q":"What is the Structure II pyramid climb like?","a":"A 45 m (148 ft) ascent on steep, uneven ancient stone, best done at first light before the tropical heat. There are no railings and the stone is slick after rain, so climb early, go with a guide for pacing, and descend facing the steps. The payoff is a canopy that rolls out like a green sea, with howler monkeys roaring in the trees below.","source":"en.wikipedia.org, 2026-07-07","si_tag":"expedition","accessed":"2026-07-07"},{"q":"Will I actually see jaguars and wildlife?","a":"You''ll see plenty, though jaguars are rare. The reserve holds Mexico''s highest jaguar density but sightings are uncommon; on a pre-dawn drive you reliably get howler and spider monkeys, toucans and many of the 365+ bird species as the canopy wakes. Stay on marked routes with a licensed guide — no approach, no touch, no feeding, and watch for fer-de-lance in the leaf litter.","source":"unep-wcmc.org, 2026-07-07","si_tag":"wildlife","accessed":"2026-07-07"},{"q":"What is the Calakmul Bat Cave?","a":"Volcán de los Murciélagos, one of only two \"bat volcano\" spectacles on Earth: an estimated 2–5 million bats erupt in a swirling vortex about an hour before dusk, off Highway 186 near km 107. Time it with a guide so the drive back out is managed in the dark, wear repellent at peak biting hour, and pack a headlamp.","source":"beyondtheordinary.co.uk, 2026-07-07","si_tag":"expedition","accessed":"2026-07-07"},{"q":"Why does Calakmul matter historically?","a":"It was the capital of the Snake Kingdom (the Kaan dynasty), the Maya superpower whose two-century rivalry with Tikal defined the Classic period until Calakmul''s defeat in 695 CE. It is a UNESCO mixed World Heritage site — culture (2002) and nature (2014) on one deed — and the nearby Río Bec route adds Becán, Chicanná, Xpujil and Balamkú''s 16.8 m stucco frieze.","source":"whc.unesco.org, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"},{"q":"How do I get to Calakmul, and does the Tren Maya reach it?","a":"The Tren Maya''s Xpujil station has run since December 2024, connecting the jungle base town to Palenque, Campeche, Bacalar and Cancún — but the final 60–110 km into the reserve is still a car. Critically, book the Xpujil station, not the isolated \"Calakmul\"-named halt, which leaves travelers stranded without services.","source":"mexicotravelandleisure.com / casakaan.com, 2026-07-07","si_tag":"access","accessed":"2026-07-07"}],"seo":{"meta_title":"Calakmul, Mexico: The Lost Maya City in the Jungle — Ruins, Jaguars & the Bat Cave | TravelWell","search_language":"es-MX","local_keywords":["ruinas de Calakmul","reserva de la biosfera Calakmul","Río Bec Xpujil","cómo llegar a Calakmul","Estructura II Calakmul pirámide","Volcán de los Murciélagos Calakmul","Tren Maya estación Xpujil"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","primary_keyword":"Calakmul","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"},{"si":"wildlife","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"property":"Hotel Puerta Calakmul","type":"cabaña lodge at reserve gate","mor":"direct/DMC","tier":"mid (ceiling)","earning":"small-property commission; value = proximity"},{"property":"Río Bec Dreams","type":"7-Jungalow eco-lodge near Becán/Chicanná","mor":"direct/DMC","tier":"comfort","earning":"direct commission; strong for Río Bec route"},{"property":"Zoh-Laguna / Xpujil cabañas","type":"village cabañas / small hotels","mor":"bedbank/direct","tier":"essential","earning":"thin margin; volume base"}],"source_verified":null,"hero":{"query":"Calakmul, Mexico, Mexico"},"geo":{"lat":18.1057,"lng":-89.8117},"orbit":[{"id":"campeche-city-mexico","jewels":11,"si":["romance"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 18),
  ('campeche-city-mexico', '10S', 'Campeche City, Mexico', 'Mexico', 'Campeche City', 'live', 'verified', 'venice', 'Campeche (Campeche City & Calakmul)', '{"culinary","culture","romance"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","air_access_verified":true,"air_notes":"CPE direct from Mexico City (Aeromexico/Mexicana); Merida MID ~2.5 hr drive as wide-body gateway","advisory_source":"https://www.gov.uk/foreign-travel-advice/mexico","health":["bottled water","heat/sun at ruins & malecon","dengue in rainy season"],"evac":"Merida tertiary care; US medevac (Miami/Houston) for critical trauma","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Nov-Mar (dry, cool; Dec-Feb sweet spot)","inflection":"early autumn demand build; Carnaval late-Feb micro-peak","fire_date":"mid-to-late September (curve-start minus 1-2 wks); +2nd fire ~2 wks pre-Carnaval","green_season":"Jun-Oct (rainy, hotter, value)","attach":"Merida / Yucatan circuit (~2.5 hr)"},"jewels":[{"name":"Walled centro — pastel streets & eight bastions","tier":"essential","source":"https://whc.unesco.org/en/list/895/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov-Mar","commission":"guided walking tour + boutique-hotel room commission (wall free)","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''guided walking tour + boutique-hotel roo''","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["hotel","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Puerta de Tierra sound-and-light show","tier":"essential","source":"https://campechecity.com/best-time-to-visit-campeche/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov-Mar","commission":"bundle into guided evening; ticket non-commissionable pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["bundle","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Fuerte de San Miguel — Museo Arqueológico de Campeche","tier":"essential","source":"https://www.lonelyplanet.com/mexico/yucatan-peninsula/campeche/attractions/museo-arqueologico-de-campeche-fuerte-de-san-miguel/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov-Mar","commission":"guided half-day + transfer margin; entry non-commissionable","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — default - a place to see or do (David 2026-10-05: fully integrated)","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Edzná Maya ruins (52 km SE)","tier":"comfort","source":"https://www.themayanruinswebsite.com/edzna.html","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"guided archaeology day tour (DMC/affiliate) + site fee pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Xtacumbilxunaán caves (near Bolonchén)","tier":"comfort","source":"https://www.lonelyplanet.com/mexico/attractions/grutas-de-xtacumbilxunaan/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Nov-Mar","commission":"guided day tour (commissionable) + entry pass-through","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Isla Aguada / Isla del Carmen dolphin encounter","tier":"comfort","source":"https://en-yucatan.com/campeche/isla-aguada/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Open-water small-boat operation, sun exposure, weather turns Guided only Confirm life vests on board and worn, weather-check the launch, no touching/chasing dolphins, motion-sickness prep","si":"romance","blurb":"Open-water small-boat operation, sun exposure, weather turns Guided only Confirm life vests on board and worn, weather-check the launch, no touching/chasing dolphins, motion-sickness prep","when":"Nov-Mar","commission":"licensed sanctuary boat tour via affiliate (GetYourGuide/Civitatis) or DMC","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["romance"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Malecón at sunset (7 km Gulf-front)","tier":"essential","source":"https://www.lonelyplanet.com/mexico/yucatan-peninsula/campeche/","timing":"year-round","timing_type":"ALWAYS-ON","si":"romance","when":"year-round","commission":"free amenity selling boutique-hotel package","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["romance"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"primary"},"commission_lane":["package","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Candlelit colonial-courtyard dining","tier":"premier","source":"https://www.marriott.com/en-us/hotels/cpehl-hacienda-puerta-campeche-a-luxury-collection-hotel-campeche/overview/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Nov-Mar","commission":"hotel F&B + room commission","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''hotel f&b + room commission''","si_all":["romance"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"primary"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Pan de cazón (state dish)","tier":"essential","source":"https://mexiconewsdaily.com/lifestyle/food/state-by-plate-campeches-pan-de-cazon/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Campechano cuisine is one of Mexico''s most distinct regional tables","si":"culinary","blurb":"Campechano cuisine is one of Mexico''s most distinct regional tables","when":"Nov-Mar","commission":"guided food walk / cooking class (tour affiliate)","wells":["eat"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","romance":"destination"},"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Pámpano en escabeche & coctel campechano","tier":"essential","source":"https://www.mexicotravelandleisure.com/blog/campeche-food-guide/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Nov-Mar","commission":"curated dining list + food tour / market visit","wells":["eat"],"wells_basis":"full pass 2026-10-05, additive — food SI (David 2026-10-05: every traveler has to eat)","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","romance":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Calakmul gateway (own dossier)","tier":"premier","source":"https://whc.unesco.org/en/list/895/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the deep-jungle Maya megacity + biosphere is a long day/overnight from Campeche City and should not be collapsed into this file","si":"culture","blurb":"the deep-jungle Maya megacity + biosphere is a long day/overnight from Campeche City and should not be collapsed into this file","when":"Nov-Mar","commission":"multi-day DMC program from Campeche City","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is there to see in the walled city?","a":"The UNESCO centro itself: a 17th-century wall (1686–1704), eight bastions, a checkerboard grid and 1,000+ colonial buildings painted ochre, coral and mint — walk Calle 59 at golden hour. At night, the Puerta de Tierra sound-and-light show projects four centuries of pirate history onto the Land Gate for about US$5.","source":"whc.unesco.org, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"},{"q":"Is Edzná worth a day trip from Campeche?","a":"Yes — it is the region''s under-visited Maya highlight. Edzná, 52 km southeast, is a major Maya capital whose five-story pyramid rises ~40 m and blends Puuc, Chenes and Petén styles, with a rare ancient hydraulic canal system and a fraction of Chichén Itzá''s crowds. Go at the 8 AM opening to beat the heat.","source":"themayanruinswebsite.com, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"},{"q":"Is Campeche good for a couple''s trip?","a":"Yes, as a slow, characterful pause. Dinner in a restored-hacienda courtyard (La Guardia at Hacienda Puerta Campeche), a rooftop pool at an 18th-century mansion, and the peninsula''s best sunset along the 7-km malecón make it a honeymoon-adjacent \"second city,\" most often paired with Mérida (~2.5 hr) as a 2–3 night add-on.","source":"lonelyplanet.com, 2026-07-07","si_tag":"romance","accessed":"2026-07-07"},{"q":"What should I eat in Campeche?","a":"Start with pan de cazón — the state dish of layered tortillas, black beans, shredded dogfish and tomato-habanero sauce. Add pámpano en escabeche (colonial-era pompano in bitter-orange escabeche) and the coctel campechano seafood cocktail, with Gulf catch landed the same morning.","source":"mexiconewsdaily.com, 2026-07-07","si_tag":"culinary","accessed":"2026-07-07"},{"q":"What''s the real risk to plan for in Campeche?","a":"Heat and thin flight schedules, not crime. The exposed ruins at Edzná and the treeless malecón are hot at midday — hat, high SPF, water and early site visits. Campeche''s own airport (CPE) is thinly served, so most travelers fly into Mérida (MID) and drive ~2.5 hr; drink bottled water only and use repellent for dengue in the rainy season (Jun–Oct).","source":"climatestotravel.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"}],"seo":{"meta_title":"Campeche City, Mexico — The Walled UNESCO Pastel Port | TravelWell.World","search_language":"es-MX","local_keywords":["qué hacer en Campeche","ciudad amurallada Campeche","Edzná zona arqueológica","hoteles boutique centro histórico Campeche","avistamiento de delfines Isla Aguada","pan de cazón Campeche","Carnaval de Campeche fechas"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","primary_keyword":"Campeche City","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"content_freshness":"2026-07-07","long_tail":["is Campeche City Mexico safe","things to do in Campeche walled city","Edzná ruins day trip from Campeche","Isla Aguada dolphin tour Campeche","best boutique hotels Campeche historic center"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"}],"ultra":[{"property":"Hacienda Puerta Campeche, a Luxury Collection Hotel","brand":"Marriott — Luxury Collection","rooms":14,"positioning":"Restored 16th-c. haciendas; the destination''s true luxury ceiling","earning":"Marriott commissionable; Luxury Collection eligible for Marriott STARS/Luxury consortia — verify FHR/amenity status at booking","mor":"hotel-direct commission","tier":"$$$$"},{"property":"Casa Don Gustavo Boutique Hotel","rooms":10,"positioning":"Restored 18th-c. mansion, rooftop pool, pedestrian center","earning":"Independent — direct / bedbank / consortia","mor":"hotel-direct or platform","tier":"$$$"},{"property":"Hotel H177","positioning":"Boutique centro property, Calle 59","earning":"Independent boutique; direct / affiliate","mor":"hotel-direct or platform","tier":"comfort"}],"source_verified":null,"hero":{"query":"Campeche City, Mexico, Mexico"},"geo":{"lat":19.845,"lng":-90.523},"orbit":[{"id":"calakmul-mexico","jewels":8,"si":["culture","wildlife","expedition"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-