  ('cancun-mexico', '10S', 'Cancún', 'Mexico', 'The gateway where a barrier reef meets a runway', 'live', 'verified', 'tropicalBeach', 'Quintana Roo (Cancún & Riviera Maya)', '{"tropical","adventure","diveglobal","ocean"}', '{"tropical"}', '{"essential","comfort"}', null, 'anchor', '{"key_facts":["Sits on the Mesoamerican Barrier Reef, world''s 2nd-longest coral reef system","MUSA underwater museum: 470+ statues, 3.5-8 m, divable and snorkelable","World''s largest whale-shark aggregation offshore mid-May to mid-Sept (snorkel-only)","Best overall window Jan-Mar (clearest water, lowest sargassum)","Gateway hub for cenotes, Chichen Itza/Tulum, Isla Mujeres and Contoy"],"safety":{"emergency":"911","hospital":"Galenia + Hospiten Cancún (verify trauma status); hyperbaric via SSS Cancún / Cozumel","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Dec-Apr (dry, lowest sargassum, highest price/crowds)","shoulder":"late Apr-Jun & Nov (~30-40% off, good weather)","green":"Jul-Oct (hurricane/rain, 40-60% below peak Sep-Oct)","booking_lead":"~3-4 months for Dec-Apr peak & spring break; 2-3 months off-peak","off_season_specials":"~30-40% off May-Jun & Nov shoulder; 40-60% off Sep-Oct green trough","event_peaks":["Spring Break (Mar)","whale-shark run mid-May-mid-Sept peak Jun-Aug","winter holidays late Dec"],"fire_date":"market Dec-Apr peak by ~September; push whale-shark green-season from ~March"},"jewels":[{"name":"MUSA Underwater Museum","status":"future","hook":"470+ submerged sculptures, divable by OW divers and snorkelers","bookable_category":"dive/snorkel/glass-bottom tour","tier":"comfort","source":"https://www.bluewaterdivetravel.com/scuba-musa-isla-mujeres-cancun","timing":"year-round","timing_type":"ALWAYS-ON","si":"diveglobal","blurb":"470+ submerged sculptures, divable by OW divers and snorkelers","when":"year-round","commission":"local dive-op/DMC → Viator/GYG affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"adventure":"destination","diveglobal":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Whale-shark aggregation run","status":"future","hook":"snorkel the world''s largest whale-shark gathering, Jun-Aug peak","bookable_category":"boat snorkel excursion","tier":"comfort","source":"https://www.islandlifemexico.com/cancun-snorkeling-diving-guide/","si":"ocean","blurb":"snorkel the world''s largest whale-shark gathering, Jun-Aug peak","commission":"DMC/operator → OTA affiliate","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["diveglobal","ocean"],"shelf_fit":{"adventure":"destination","diveglobal":"evidenced","ocean":"primary","tropical":"destination"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Route of the Cenotes","status":"live","hook":"jungle-road cenote circuit for swim/dive/zipline","bookable_category":"day tour + entry","tier":"essential","source":"https://www.islandlifemexico.com/cancun-snorkeling-diving-guide/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"jungle-road cenote circuit for swim/dive/zipline","when":"Dec-Apr","commission":"DMC → OTA (entry = pass-through)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","diveglobal"],"shelf_fit":{"adventure":"primary","diveglobal":"evidenced","ocean":"destination","tropical":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Turtle-nesting programs (May-Sept)","status":"live","hook":"green/hawksbill/loggerhead nesting + resort release programs","bookable_category":"eco/resort activity","tier":"essential","source":"https://www.islandlifemexico.com/cancun-snorkeling-diving-guide/","si":"adventure","blurb":"green/hawksbill/loggerhead nesting + resort release programs","commission":"resort/DMC (often pass-through)","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["adventure"],"shelf_fit":{"adventure":"primary","diveglobal":"destination","ocean":"destination","tropical":"destination"},"commission_lane":["DMC","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"South Hotel Zone / Playa Mujeres (sargassum-protected)","status":"live","hook":"cleaner beach stretches in a heavy sargassum year","bookable_category":"hotel + transfer","tier":"comfort","source":"https://www.howisthesargassum.com/blog/sargassum-june-2026-update","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","blurb":"cleaner beach stretches in a heavy sargassum year","when":"Dec-Apr","commission":"all-inclusive portal → Amstar transfer → OTA","wells":["activities","move","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["tropical"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","ocean":"destination","tropical":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"What health risks should I actually plan for in Cancún?","a":"Water, mosquitoes, hurricanes and sargassum — not violent crime. Drink bottled/purified water; use repellent for dengue (no malaria in Quintana Roo tourist zones); hurricane season runs June–November with September riskiest; and sargassum peaks around July in 2026.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"Will sargassum ruin the beaches in 2026?","a":"It''s a real risk in 2026 — plan location, don''t cancel. 2026 is tracking as one of the worst sargassum years on record, often peaking around July in the Riviera Maya; north Cancún and Playa Mujeres are among the more protected stretches, and Jan–March runs lowest on sargassum.","source":"howisthesargassum.com","si_tag":"tropical"},{"q":"When and how can I swim with whale sharks?","a":"Mid-May to mid-September, peaking June–August, on a snorkel-only boat excursion off Isla Mujeres/Holbox — the world''s largest whale-shark aggregation. It''s a green-season spike inside the low-price window, so rooms are cheaper then; life-vest, no-touch, follow-the-guide.","source":"islandlifemexico.com","si_tag":"ocean"},{"q":"Can beginners dive MUSA and the reef?","a":"Yes — MUSA is one of the most accessible dives anywhere. The 470+ statues sit 3.5–8 m down, shallow enough for Open Water divers, snorkelers and glass-bottom boats; no-fly-after-diving is 18–24 hours and these are shallow (≤9 m) day dives.","source":"bluewaterdivetravel.com","si_tag":"diveglobal"},{"q":"Is Cancún good for an all-inclusive honeymoon, and where''s the top end?","a":"Yes — it''s a honeymoon engine. The Hotel Zone is dense all-inclusive inventory; the one true ultra address in Cancún proper is NIZUC (Punta Nizuc, ~15 min from the airport), with the deepest luxury bench just down-corridor in Mayakoba/Maroma (Rosewood, Banyan Tree, Maroma/Belmond).","source":"virtuoso.com","si_tag":"tropical"}],"seo":{"meta_title":"Cancún, Mexico: Reef, MUSA & Whale-Shark Gateway","meta_description":"Cancún sits on the world''s second-longest reef — dive MUSA, snorkel the whale-shark run, base for cenotes and Maya ruins. Best time, safety, and how to book.","slug":"cancun-mexico","primary_keyword":"Cancún diving and snorkeling","long_tail":["Cancún MUSA underwater museum","Cancún whale shark tour season","best time to visit Cancún","Cancún all-inclusive honeymoon","Cancún cenote day trip"],"search_language":"EN primary + ES-MX; page answers real ES queries restated (not machine-translated)","local_keywords":["mejor época para viajar a Cancún","buceo MUSA Cancún","tour tiburón ballena Cancún","qué hacer en Cancún cenotes","Cancún todo incluido luna de miel","temporada de sargazo Cancún","villas de lujo Riviera Maya"],"hreflang":["en","es-MX","x-default:en"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"codes":[],"note":"MXN currency, USD widely accepted","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-07-31","hits":9,"misses":13,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live"},{"si":"globaladv","name":"adventure","status":"live"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"NIZUC Resort & Spa","why_ultra":"only true in-Cancún ultra enclave (Punta Nizuc), 274 suites/villas facing the reef","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Virtuoso member — free upgrades + amenities","mor":"safe (commissionable-rack / Virtuoso)"},{"name":"Rosewood Mayakoba","why_ultra":"boutique ~130 lagoon/beach suites, private pools + butler, on mangrove canals","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Virtuoso member","mor":"safe (commissionable-rack)"},{"name":"Banyan Tree Mayakoba","why_ultra":"all-villa private-pool privacy inside Mayakoba","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Virtuoso member","mor":"safe (commissionable-rack)"},{"name":"Fairmont Mayakoba","why_ultra":"full-amenity luxury tier of the Mayakoba four","earning":"agent/consortium on application via host","virtuoso_value_add":"verify (reported NOT Virtuoso; check Accor ALL/other)","mor":"safe (commissionable-rack)"},{"name":"Chablé Maroma","why_ultra":"wellness-forward design ultra, private beach, Jorge Vallejo dining","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"verify present","mor":"safe (commissionable-rack)"},{"name":"Maroma, A Belmond Hotel","why_ultra":"legendary private-beach ultra, Belmond/LVMH tier","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Belmond typically Virtuoso — verify","mor":"safe (commissionable-rack)"},{"name":"La Casa de la Playa (by Xcaret)","why_ultra":"Xcaret''s top-tier ultra all-inclusive, adults/couples + eco-park access","earning":"agent/consortium via Xcaret trade / host on application","virtuoso_value_add":"verify","mor":"safe (commissionable-rack)"}],"source_verified":"2026-07-04","hero":{"query":"Cancún, Mexico"},"geo":{"lat":21.1619,"lng":-86.8515},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-contoy-mexico","jewels":3,"si":["expedition","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"playa-del-carmen-mexico","jewels":5,"si":["romance","expedition","diveglobal","culture"]},{"id":"puerto-aventuras-mexico","jewels":5,"si":["romance","diveglobal","ocean","wildlife"]},{"id":"puerto-morelos-mexico","jewels":5,"si":["diveglobal","ocean","adventure","c