  ('careyes-mexico', '10S', 'Careyes (Costa Careyes)', 'Mexico', 'Careyes Mexico', 'live', 'verified', 'luxuryPool', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"ocean","romance","ultra"}', '{}', '{"premier","luxury","ultra"}', null, null, '{"key_facts":["Founded 1968 by Gian Franco Brignone; 48-room beach hotel, 36 casitas, ~50 villas + clifftop castles with moat-like infinity pools","Villas privately owned, many rent fully staffed with private cook + daily housekeeping","Polo late-Nov->end-Apr (Agua Alta Cup at Easter, Chinese New Year tournament); Ondalinda x Careyes Nov 12-15 2026","Hosted Heidi Klum & Seal wedding; Tom Ford, Naomi Campbell, Uma Thurman have vacationed","Between PVR and Manzanillo (ZLO ~1.5-hr drive); private charters to Chamela strip CHM31 ~15 min / Chalacatepec ~40 min; Cuixmala & Las Alamandas have own airstrips"],"safety":{"emergency":"911","hospital":"remote enclave; serious cases route to Manzanillo (~1.5 hr) or Puerto Vallarta (~2-4 hr); private airstrips serve medical evac; carry travel-medical + air-evac insurance","air_access_verified":"private airstrip (Careyes/Cuixmala) + Manzanillo ZLO - flag for founder review","founder_flag":"gated resort enclaves with private airstrips - candidate ''resort-airstrip private-access'' clean-pass class; per gate test content-only until founder rules; LUX ultra moat","malaria":"low - mosquito avoidance (not prophylaxis) for Jalisco coastal lowlands below 1,000 m","dengue":"circulates (peak May-Nov) - daytime repellent","water":"bottled/purified (staffed villas provide)","hurricane":"May-Nov - trip insurance for summer/fall","remote":"minimal public services outside enclave; do NOT drive secondary roads after dark (advisory warning)","road_transfer":"PVR/Manzanillo transfers pass through non-carve-out southern Jalisco - the hold reason; private-air arrival is the founder-flag workaround","dive":"nearest hyperbaric chambers Puerto Vallarta & Manzanillo (1.5-4 hr) - conservative profiles, DAN insurance, strict no-fly interval","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Nov-Apr (dry season, polo/Ondalinda/celebrity winter season, holiday villa demand, humpbacks Dec-Mar)","shoulder":"May & late Oct (warm, quieter, between festivals)","green":"Jul-Oct (hot/humid, emerald hills, hurricane window May-Nov, softest villa availability)","event_peak":"polo late-Nov->end-Apr (Agua Alta Cup at Easter, Chinese New Year tournament); Ondalinda x Careyes Nov 12-15 2026","out_of_season_fill_the_beds":"green season (Jul-Oct) villa buyouts at softer rates as private-family estate stays (turtle nesting Cuixmala) - the ''secret season''","sources":["https://www.ondalinda.com/festivals/careyes/","https://careyes.com/","https://mexiconewsdaily.com/travel/an-insiders-guide-to-the-perfect-weekend-in-costalegre/"],"fire_date":"content-only - no campaign; if founder rules private-air carve-out, open winter/polo/Ondalinda villa campaigns in spring for following Nov-Apr peak (6-12-mo villa lead)","event_peaks":"Christmas-New Year (ultra premium), Semana Santa/Easter (Agua Alta Cup polo), Chinese New Year (polo+gala), Ondalinda (mid-Nov)","booking_lead":"staffed ultra villas for Christmas-New Year/winter polo/Ondalinda book 6-12 months ahead, contracted direct on application; binding constraint is villa availability, not flights"},"jewels":[{"name":"Careyes clifftop Castles","status":"future","tier":"ultra","bookable":"Careyes reservations / villa specialist","source":"https://careyes.com/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"candy-colored castles with moat-like infinity pools cantilevered over the Pacific — the signature Careyes image","si":"ultra","blurb":"candy-colored castles with moat-like infinity pools cantilevered over the Pacific — the signature Careyes image","when":"year-round","commission":"on application","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ultra"],"shelf_fit":{"ocean":"destination","romance":"destination","ultra":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Cuixmala (Casa Cuixmala suites / hillside villas)","status":"future","tier":"ultra","bookable":"Cuixmala direct / luxury DMC","source":"https://www.luxurylatinamerica.com/mexico/cuixmala.html","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Goldsmith''s 25,000-acre biosphere estate — zebras, nesting turtles, private airstrip, total seclusion","si":"ultra","blurb":"Goldsmith''s 25,000-acre biosphere estate — zebras, nesting turtles, private airstrip, total seclusion","when":"Nov-Apr","commission":"on application","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ultra"],"shelf_fit":{"ocean":"destination","romance":"destination","ultra":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Las Alamandas","status":"future","tier":"ultra","bookable":"Las Alamandas direct / DMC","source":"https://www.alamandas.com/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"18 suites across 8 villas, plus 16% VAT / 3% room tax / 14% service. On application","si":"ultra","blurb":"18 suites across 8 villas, plus 16% VAT / 3% room tax / 14% service. On application","when":"Nov-Apr","commission":"on application","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["ultra"],"shelf_fit":{"ocean":"destination","romance":"destination","ultra":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Careyes staffed-villa honeymoon","status":"future","tier":"ultra","bookable":"Careyes reservations / villa specialist","source":"https://careyes.com/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"private staffed villa/casita with cook, cliff-and-cove privacy — a celebrity-wedding coast","si":"romance","blurb":"private staffed villa/casita with cook, cliff-and-cove privacy — a celebrity-wedding coast","when":"Nov-Apr","commission":"on application","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","ultra"],"shelf_fit":{"ocean":"destination","romance":"primary","ultra":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_basis":"tier==''ultra'' implies the ultra interest; gen_ultra_from_tier"},{"name":"El Careyes Club & Residences","status":"future","tier":"luxury","bookable":"Careyes reservations","source":"https://careyes.com/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"beachfront club stay for couples wanting hotel-style service inside the enclave","si":"romance","blurb":"beachfront club stay for couples wanting hotel-style service inside the enclave","when":"Nov-Apr","commission":"on application","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"ocean":"destination","romance":"primary","ultra":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Careyes polo - Agua Alta Cup (Easter)","status":"future","tier":"premier","bookable":"Careyes events / villa package","source":"https://www.ondalinda.com/festivals/careyes/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the enclave''s signature spectacle, played Easter week; Chinese New Year tournament too","si":"ocean","blurb":"the enclave''s signature spectacle, played Easter week; Chinese New Year tournament too","when":"Nov-Apr","commission":"on application","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — default - a place to see or do (David 2026-10-05: fully integrated)","si_all":["ocean"],"shelf_fit":{"ocean":"primary","romance":"destination","ultra":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Sailing + winter humpback coast","status":"future","tier":"luxury","bookable":"charter / villa concierge (content-only)","source":"https://www.costalegre.ca/","hook":"sailing off the coves; humpbacks migrate Dec–Mar offshore","si":"ocean","blurb":"sailing off the coves; humpbacks migrate Dec–Mar offshore","commission":"operator (content-only)","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"ocean":"primary","romance":"destination","ultra":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Can I book Careyes through TravelWell right now?","a":"No — Careyes is content-only today. Failing that named-carve-out gate sets book_enabled=FALSE.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"What''s the real risk to plan for at Careyes?","a":"The road transfer, not the enclave itself. Ground transfers from Puerto Vallarta or Manzanillo run through non-carve-out southern Jalisco, and the advisory warns specifically against secondary highways after dark — this is the hold reason. The enclave is also remote: serious medical cases route ~1.5 hr to Manzanillo or 2–4 hr to Puerto Vallarta, so air-evac insurance is essential.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"What makes Careyes so exclusive?","a":"It is a genuinely private, family-owned ultra node — not a resort. Founded in 1968, it pairs clifftop castles and ~50 staffed villas with two adjacent Goldsmith estates: Cuixmala, a ~25,000-acre biosphere reserve with its own airstrip, and Las Alamandas, an 18-suite gated boutique. All three have private airstrips — the crux of a possible future \"arrive-by-private-air\" clean pass.","source":"luxurylatinamerica.com / careyes.com, 2026-07-04","si_tag":"ultra","accessed":"2026-07-04"},{"q":"Is Careyes good for a honeymoon or wedding?","a":"Yes — it is one of Mexico''s most cinematic private-wedding coasts. Heidi Klum and Seal married here, and the product is a fully staffed villa or casita with a private cook and total cliff-and-cove privacy, plus El Careyes Club & Residences for hotel-style service. Peak is the dry Nov–Apr season, and villas for that window contract 6–12 months ahead.","source":"careyes.com / aol.com, 2026-07-04","si_tag":"romance","accessed":"2026-07-04"},{"q":"When is polo season and the Ondalinda festival?","a":"Professional polo runs late November to the end of April, with the marquee Agua Alta Cup played Easter week and a Chinese New Year tournament; the Ondalinda x Careyes festival is dated Nov 12–15, 2026. Winter also brings humpbacks offshore (Dec–Mar). Staffed-villa demand for these dates books 6–12 months out.","source":"ondalinda.com, 2026-07-04","si_tag":"ocean","accessed":"2026-07-04"}],"seo":{"meta_title":"Careyes Mexico: Clifftop Castles, Polo & the Costalegre Ultra Coast","meta_description":"Careyes — Gian Franco Brignone''s 1968 private ultra enclave on Jalisco''s Costalegre: clifftop castles, staffed villas, polo, sailing, Ondalinda, plus Cuixmala & Las Alamandas.","slug":"careyes-mexico","primary_keyword":"Careyes Mexico","long_tail":["Careyes villas rent","Careyes clifftop castles","Careyes polo Agua Alta Cup","Ondalinda Careyes 2026","Cuixmala vs Careyes vs Las Alamandas","Careyes private airstrip access"],"search_language":["en","es-MX"],"local_keywords":["Careyes Mexico","villas Careyes renta","castillos Careyes","polo Careyes Copa Agua Alta","Ondalinda Careyes 2026","Cuixmala reserva","Las Alamandas Costalegre"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"Luxury / Ultra-Luxury","status":"future"},{"si":"romance","status":"future"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Cuixmala","posture":"Goldsmith ~25,000-acre private biosphere estate; suites/villas/casitas; zebras+turtles; private airstrip","price_tier":"ultra","earning":"on application / luxury DMC (Journey Mexico) / villa specialist","virtuoso_value_add":"likely via luxury-DMC channel - verify at contract","mor":"no net-rate resale","book_gated":"founder carve-out decision (private-airstrip clean-pass class)","source":"https://www.luxurylatinamerica.com/mexico/cuixmala.html"},{"name":"Careyes (Casitas / Castles)","posture":"Brignone 1968 clifftop enclave; hotel + casitas + ~50 villas + moat-pool castles; polo/sailing/Ondalinda; private-air via Chamela CHM31 ~15 min","price_tier":"ultra","earning":"on application / villa specialist","virtuoso_value_add":"verify at contract","mor":"no net-rate resale","book_gated":"founder carve-out decision","source":"https://careyes.com/"},{"name":"Las Alamandas","posture":"Isabel Goldsmith 18-suite gated ultra-boutique on private bay; own 3,300-ft asphalt airstrip (currently unavailable - use Chamela strip 15 min)","price_tier":"ultra","earning":"on application / DMC","virtuoso_value_add":"likely via luxury-DMC channel - verify","mor":"no net-rate resale","book_gated":"founder carve-out decision","source":"https://www.alamandas.com/"},{"name":"El Careyes (Club & Residences)","posture":"beachfront club/residences arm of the Careyes enclave","price_tier":"luxury","earning":"on application","virtuoso_value_add":"verify at contract","mor":"no net-rate resale","book_gated":"founder carve-out decision","source":"https://careyes.com/"}],"source_verified":"2026-07-04","hero":{"query":"Careyes (Costa Careyes), Mexico"},"geo":{"lat":19.4,"lng":-105.03},"orbit":[{"id":"chapala-ajijic-mexico","jewels":6,"si":["wellness","culture","senior"]},{"id":"costalegre-mexico","jewels":7,"si":["tropical","romance","ultra","ocean"]},{"id":"guadalajara-mexico","jewels":8,"si":["culture","culinary","entertainment","sports"]},{"id":"mazamitla-mexico","jewels":6,"si":["expedition","family","adventure"]},{"id":"puerto-vallarta-mexico","jewels":5,"si":["romance","expedition","ocean"]},{"id":"san-sebastian-del-oeste-mexico","jewels":6,"si":["culture","expedition","culinary"]},{"id":"tlaquepaque-mexico","jewels":4,"si":["culture","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","celestun-mexico","chichen-itza-mexico","coba-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 21),
  ('caye-caulker-belize', '10S', 'Caye Caulker', 'Belize', 'Caye Caulker Belize', 'live', 'verified', 'tropicalBeach', 'Belize', '{"tropical","liveaboard","expedition","ocean","culinary"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["Car-free ~5-mi caye; golf carts + bikes only; national motto ''Go Slow''; reached by water taxi (~45 min from Belize City) or Tropic Air / Maya Island Air airstrip","The Split = channel hand-widened after Hurricane Hattie (1961), now ~100 ft deep; island''s social heart + Lazy Lizard bar","Snorkel/dive base for the Belize Barrier Reef (UNESCO); Hol Chan Marine Reserve US$15 park fee (Belize''s oldest marine park)","Value counterpoint to Ambergris - budget-to-comfort island; hotel ceiling is boutique (Iguana Reef Inn / Weezie''s), no branded ultra on-island","Ragga 3-day/2-night sail Caulker->Placencia via Blue Hole/reef (~US$400, chef, Tue/Fri); manatees at Swallow Caye Wildlife Sanctuary (10 BZD fee)"],"safety":{"emergency":"911 (verify locally)","hyperbaric_chamber":"NOT on Caye Caulker - nearest is San Pedro/Ambergris Caye (Belize''s only chamber, next to Ambergris Hope Clinic, 226-2660); Caulker dive-accident cases boated to San Pedro - factor transfer time","hospital":"small local clinic on-caye; serious trauma routes to Belize City hospitals by water taxi/air or air-evac; route around Southside Belize City","l3_disclosure":true,"stay_in_zone":true,"air_access_verified":"BZE -> Caye Caulker (CUK) by Tropic Air / Maya Island Air puddle-jumper, or high-speed water taxi ~45 min; never touches Southside Belize City","founder_policy_note":"only Southside Belize City is the named danger","the_split":"tidal current + boat traffic in the channel; not lifeguarded/boat-free; swim to sides, watch for boats, don''t swim impaired","malaria":"WHO-certified malaria-free (2023); a few mainland Cayo cases reappeared 2025; effectively none on the caye","dengue":"dengue/chikungunya/Zika active (daytime Aedes; Belize City cases up 2025) - DEET/picaridin, cover up","water":"tap water NOT potable - bottled/filtered only; mind ice/raw produce/unpasteurized dairy","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-09-01T16:20:07Z","page_updated":"2026-06-12T10:40:30+01:00","source_country":"belize","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","dive_emergency_numbers_verified":{"read":"2026-08-30","numbers":{"226-2660":"Belize Chamber Project, San Pedro, 24/7 — sanpedrosun.com / ambergriscaye.com, read 2026-08-30"},"_rule":"Each number above was read from the authority named beside it on the date shown. ⛔ A number with no entry here has NOT been verified and must not be presented as an emergency contact."}},"timing":{"peak":"late-Dec-Apr (dry high season; Jan-Mar driest; Christmas-New Year + Easter sub-peaks)","dive_subpeak":"Mar-Jun (best viz, Blue Hole conditions)","shoulder_green":"Sep-Nov (green/rainy; Sep-Oct highest hurricane risk = value trough; late-Nov flips to dry comfort at low rates)","out_of_season_fill_the_beds":"dive/sail value packages, Lobsterfest tail, manatee + Goff''s Caye day trips, ''slow island at half price'', Nov dry-comfort-at-low-rates","fire_date":"peak: early-to-mid November (curve-start late-Nov minus 1-2 wks); dive/expedition: mid-February; green-value Nov push: late September; keep rolling last-minute layer year-round","flag":"value/short-lead market moves the curve faster than resort markets; Sep-Oct hurricane risk overlaps green window - sharpen on live booking-pace tracking","sources":["https://www.ashtoncourtbelize.com/blog/when-is-the-best-time-to-visit-caye-caulker.html","https://www.zubludiving.com/destination/belize/belize-district/ambergris-caye-san-pedro-caye-caulker","https://www.raggasailadventures.com/","https://www.thoroughlytravel.com/hotels-caye-caulker/"],"event_peaks":"Christmas-New Year, Easter, Lobsterfest (July), Independence season (Sep, overlaps hurricane risk)","booking_lead":"value/short-lead market (weeks to a few months); 2-4 months for Dec-Apr peak + Christmas/Easter; book Blue Hole / 3-day Ragga sail ahead"},"jewels":[{"name":"The Split + Lazy Lizard sunset swim","timing":"year-round, best sunset","tier":"essential","source":"https://en.wikipedia.org/wiki/Caye_Caulker","si":"tropical","when":"year-round, best sunset","commission":"F&B/OTA-adjacent scene-setter, not a margin line","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"hand-cut channel, crystal water, the island''s social heart at golden hour","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["tropical"],"shelf_fit":{"culinary":"destination","expedition":"destination","liveaboard":"destination","ocean":"destination","tropical":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Bike / golf-cart the car-free island","timing":"year-round","tier":"essential","source":"https://www.nomadicmatt.com/travel-guides/belize-travel-tips/caye-caulker/","si":"tropical","when":"year-round","commission":"local rental affiliate / DMC add-on","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"the whole Go Slow experience in an afternoon","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["tropical"],"shelf_fit":{"culinary":"destination","expedition":"destination","liveaboard":"destination","ocean":"destination","tropical":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Hol Chan Marine Reserve + Shark Ray Alley","timing":"year-round, best viz Mar-Jun","tier":"essential","source":"https://www.backpackerswanderlust.com/caye-caulker-snorkeling-tours/","si":"liveaboard","when":"year-round, best viz Mar-Jun","commission":"local dive/snorkel operator + Viator/GYG affiliate; CLIA dive-lane convert to commissioned where offered","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"Belize''s oldest marine park; sharks/rays/turtles; US$15 fee","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["liveaboard"],"shelf_fit":{"culinary":"destination","expedition":"destination","liveaboard":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Coral Gardens + seahorse stop","timing":"year-round","tier":"essential","source":"https://www.getyourguide.com/caye-caulker-l2496/caye-caulker-7-stop-snorkeling-in-the-belize-barrier-reef-t364340/","si":"liveaboard","when":"year-round","commission":"local operator + GYG affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"shallow coral + seahorses on mangrove/grass roots - the caye''s signature soft moment","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["liveaboard"],"shelf_fit":{"culinary":"destination","expedition":"destination","liveaboard":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Manatee + Goff''s Caye day tour (Swallow Caye Sanctuary)","timing":"late-Dec-Apr","tier":"comfort","source":"https://www.thoroughlytravel.com/swimming-with-manatees-belize/","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"late-Dec-Apr","commission":"local operator + DMC + Viator affiliate (10 BZD sanctuary fee non-commissionable)","wells":["eat","activities"],"wells_basis":"derived from name/blurb/hook","blurb":"West Indian manatees in a protected sanctuary + sandbar-caye lunch","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["expedition"],"shelf_fit":{"culinary":"destination","expedition":"primary","liveaboard":"destination","ocean":"destination","tropical":"destination"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ragga 3-day sail to Blue Hole / Placencia","timing":"year-round, Tue/Fri departures","tier":"comfort","source":"https://www.raggasailadventures.com/","si":"expedition","when":"year-round, Tue/Fri departures","commission":"Ragga tour commission on application + dive-lane crossover","wells":["activities","eat","move","stay"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"sail the reef, camp on cayes, chef-cooked lobster on deck - the caye''s bucket-list expedition","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["adventure","culinary","expedition","ocean","tropical"],"shelf_fit":{"adventure":"evidenced","culinary":"evidenced","expedition":"primary","liveaboard":"destination","ocean":"evidenced","tropical":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Global Expedition Adventures / Ocean Adventures","si_map_basis":"normalised from free text ''Global Expedition Adventures / Ocean Adventures'' by gen_normalise_jewel_si"},{"name":"Sunset sailing cruise","timing":"year-round evenings","tier":"essential","source":"https://www.raggasailadventures.com/","si":"ocean","when":"year-round evenings","commission":"local operator + affiliate","wells":["move","activities"],"wells_basis":"derived from name/blurb/hook","blurb":"casual catamaran sundowner off the reef","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["ocean","tropical"],"shelf_fit":{"culinary":"destination","expedition":"destination","liveaboard":"destination","ocean":"primary","tropical":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Fry-jack breakfast + lobster season / Lobsterfest","timing":"Lobsterfest July; lobster Jun-Feb","tier":"essential","source":"https://www.nomadicmatt.com/travel-guides/belize-travel-tips/caye-caulker/","si":"culinary","when":"Lobsterfest July; lobster Jun-Feb","commission":"F&B/event affiliate-adjacent","wells":["eat"],"wells_basis":"full pass 2026-10-05, additive — food SI (David 2026-10-05: every traveler has to eat)","blurb":"fried-dough island breakfast; July Lobsterfest; lobster in-season ~mid-Jun-mid-Feb","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["culinary","tropical"],"shelf_fit":{"culinary":"primary","expedition":"destination","liveaboard":"destination","ocean":"destination","tropical":"evidenced"},"commission_lane":["affiliate","event"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Kitesurfing off the reef flats","timing":"~Nov-Jun windier window","tier":"comfort","source":"https://www.backpackerswanderlust.com/caye-caulker-snorkeling-tours/","si":"ocean","when":"~Nov-Jun windier window","commission":"local kite school + affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","blurb":"steady trade-wind flats for kite","blurb_note":"recovered from orphaned field `why` 2026-08-22","si_all":["ocean","tropical"],"shelf_fit":{"culinary":"destination","expedition":"destination","liveaboard":"destination","ocean":"primary","tropical":"evidenced"},"commission_lane":["affiliate","school"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"How do you get around Caye Caulker — do you need a car?","a":"No cars at all. The ~5-mile island runs on bikes (from ~15 BZD/day) and golf carts (~125–150 BZD/day) on sand streets, reached by high-speed water taxi (~45 min from Belize City) or small plane on the Tropic Air / Maya Island Air airstrip. The whole \"Go Slow\" experience is walkable and bikeable in an afternoon.","source":"nomadicmatt.com, 2026-07-06","si_tag":"tropical","accessed":"2026-07-06"},{"q":"Is Caye Caulker good for snorkeling and diving?","a":"Yes — it is a value snorkel/dive base on the same Belize Barrier Reef as Ambergris. The Hol Chan Marine Reserve trip (US$15 park fee) puts you with sharks, rays and turtles in Belize''s oldest marine park; local operators run half-days ~US$50 and full-days ~US$90, with best visibility March–June.","source":"backpackerswanderlust.com, 2026-07-06","si_tag":"liveaboard","accessed":"2026-07-06"},{"q":"Can you sail to the Blue Hole from Caye Caulker?","a":"Yes — the Ragga 3-day/2-night sail (~US$400, Tuesday/Friday departures) runs Caulker to Placencia via the Blue Hole and reef, camping on tiny cayes with chef-cooked lobster on deck. Day options add manatees at Swallow Caye Wildlife Sanctuary (10 BZD sanctuary fee).","source":"raggasailadventures.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"What''s the food and lobster scene on Caye Caulker?","a":"Fry-jack breakfasts and beach BBQ anchor the everyday scene, and Lobsterfest lands in July as the island''s biggest food event. Lobster season itself runs roughly mid-June to mid-February, so a summer visit catches both the festival and fresh lobster.","source":"nomadicmatt.com, 2026-07-06","si_tag":"culinary","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for on Caye Caulker?","a":"Two things: there is no recompression chamber on Caulker (nearest is San Pedro/Ambergris, so dive-accident cases are boated across — build in transfer time and carry DAN), and The Split is not a lifeguarded beach. The channel has tidal current and boat traffic, so swim to the sides, watch for boats, and don''t swim impaired at the Lazy Lizard. Hurricane risk peaks Sep–Oct.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"Is diving the Blue Hole from here dangerous?","a":"It is a deep dive (>100 ft) for experienced/advanced divers only — verify certification and operator briefing. Allow 18–24 hours before flying, because many guests leave BZE by puddle-jumper, and remember the nearest chamber is on Ambergris, so plan conservative profiles and factor the boat transfer time.","source":"zubludiving.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Caye Caulker Belize: The ''Go Slow'' Island Guide","meta_description":"Snorkel Hol Chan with sharks and rays, swim The Split at sunset, sail the Blue Hole — Caye Caulker is Belize''s car-free ''Go Slow'' caye and the value counterpoint to Ambergris. When, how, and how to stay safe.","slug":"caye-caulker-belize","primary_keyword":"Caye Caulker Belize","long_tail":["Caye Caulker Go Slow island","The Split Caye Caulker swimming","Caye Caulker snorkeling Hol Chan","Caye Caulker vs Ambergris Caye budget","how to get to Caye Caulker from Belize City","Raggamuffin Blue Hole 3-day sail","Caye Caulker where to stay budget"],"search_language":"en","local_keywords":["Cayo Caulker Belice","bucear Cayo Caulker","snorkel Hol Chan Belice","cómo llegar a Cayo Caulker","hoteles económicos Cayo Caulker"],"hreflang":["en"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-08-20T14:53:57Z","source_updated":"2026-06-12T10:40:30+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"liveaboard","status":"live"},{"si":"expedition","status":"live"},{"si":"ocean","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Cayo Espanto","location":"private island 3 mi off San Pedro / Ambergris Caye","posture":"true branded ultra (nearest) - 7 villas incl. overwater Casa Ventanas, all-inclusive, houseman service, celebrity hideaway","price_tier":"ultra","rate_note":"~US$1,395-3,195/night meals incl., 4-night min","earning":"Fora / host-Virtuoso lane - commission on application","mor":"commissionable only where offered; no net-rate resale","source":"https://www.mrandmrssmith.com/luxury-hotels/cayo-espanto"},{"name":"Placencia peninsula (Itz''ana / Naia + peers)","location":"mainland-south Belize","posture":"alternate ultra/luxury base; 3-day Ragga sail ends near Placencia so Caulker+Placencia chain naturally","price_tier":"ultra/luxury","earning":"Fora / host-Virtuoso - on application","mor":"no net-rate resale","source":"https://www.raggasailadventures.com/"},{"name":"Caye Caulker on-island","posture":"STRAIGHT: NO branded ultra on-caye; ceiling = comfortable boutique guesthouse (Iguana Reef Inn / Weezie''s); sell as day/character add to an Ambergris or Placencia ultra base","price_tier":"premier (ceiling)","earning":"n/a for ultra","mor":"no net-rate resale","source":"https://www.thoroughlytravel.com/hotels-caye-caulker/"}],"source_verified":"2026-07-06","hero":{"query":"Caye Caulker, Belize"},"geo":{"lat":17.7444,"lng":-88.025},"orbit":[{"id":"ambergris-caye-belize","jewels":11,"si":["tropical","liveaboard","romance","expedition"]},{"id":"blue-hole-belize","jewels":8,"si":["liveaboard","expedition","tropical"]},{"id":"hopkins-belize","jewels":8,"si":["tropical","expedition","culture"]},{"id":"placencia-belize","jewels":8,"si":["liveaboard","expedition","diveglobal","ocean","wildlife","culture"]},{"id":"san-ignacio-belize","jewels":13,"si":["expedition","culture","romance"]}],"orbit_country":[]}'::jsonb, 22)
