xico","puerto-morelos-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 24),
  ('chichen-itza-mexico', '10S', 'Chichén Itzá', 'Mexico', 'Chichén Itzá', 'live', 'verified', 'kyoto', 'Yucatán (Mérida & Chichén Itzá)', '{"culture","expedition","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["UNESCO World Heritage Site + one of the New Seven Wonders; opens 8:00 AM, last entry 4 PM, closes 5 PM","Spring-equinox serpent-shadow (Kukulcan descending El Castillo) ~Mar 20-21, 4:30-5:10 PM; 8,400+ visitors 2026; autumn equinox ~Sep 22-23","Climbing El Castillo BANNED since 2008 (INAH); unauthorized climb fines ~55,760-278,800 MXN (~US$3,200-16,000) as of 2025","Cenote Ik Kil ~3 km away - ~60 m wide, ~40 m deep open sinkhole; entry ~250 MXN (520 w/ buffet); swim/snorkel, no lifeguard","Balankanche grotto - guided >1 km Maya-Toltec ritual cave, ~10 m descent; entrance to the underworld"],"safety":{"emergency":"911","hospital":"rural zone; nearest trauma care Merida (~2 hr W, Star Medica/Clinica de Merida) or Cancun (~2 hr E, Hospiten/Amerimed) or air-evac","air_access_verified":"yes - MID Merida ~2 hr W or CUN Cancun ~2 hr E; Chichen sits between","heat":"PRIMARY RISK - large open shadeless site in intense Yucatan sun; go at 8:00 AM opening, carry 1.5-2 L water, sun hat + high SPF; heat exhaustion #1 incident risk; equinox afternoons = long standing in heat + crowds","cenote":"Ik Kil = swim/snorkel only, NO lifeguard; provided life jackets (mandatory posture for non-swimmers/children); shower off sunscreen; steep wet stairs. Balankanche = guided dry-cave walk only, not a dive site","dive_no_fly":"Chichen NOT a scuba destination (Ik Kil/Balankanche are swim/walk). Nearest hyperbaric chambers on coast (SSS/DAN Cancun, Playa, Cozumel; SSS Merida) ~2+ hr away; DAN says nearest hospital first","malaria":"effectively none in tourist zone","dengue":"active in Yucatan 2026; chikungunya/Zika circulate - use repellent at grotto/cenote","water":"bottled/purified only","hurricane":"Jun-Nov","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"inflection_curve_start":"late January (spring-equinox bed/tour demand hardens Jan-Feb for the ~Mar 20-21 window)","peak":"dry season Nov-Apr (Dec-Jan busiest w/ Riviera Maya high season); SPRING EQUINOX ~Mar 20-21 is the single event peak (8,400+ visitors 2026, shadow 4:30-5:10 PM)","fire_date":"2027-01-08 (curve-start minus 1-2 wks; fire the spring-equinox campaign before beds/early-entry sell out)","shoulder":"May + Oct; autumn equinox ~Sep 22-23 is a green-window mini-spike","green":"Jun-Sep (extreme heat/humidity, hurricane-season afternoon rain) - go at 8:00 AM opening; sell Ik Kil as heat counterweight","booking_lead":"day-trip/excursion days-to-weeks; EQUINOX exception - book beds + guided early entry months ahead (Jan-Feb) for March","off_season_specials":"green window: anchor Chichen as marquee day-trip inside a Merida hacienda-circuit or Valladolid Pueblo-Magico stay; push autumn equinox as crowd-lighter alt to March","event_peaks":"Spring equinox ~Mar 20-21 (#1); autumn equinox ~Sep 22-23 (#2); Christmas-New Year, Semana Santa; free-Sunday crowds (Mexican nationals/residents)","note":"sharpen on live tracking - confirm 2027 equinox date + exact shadow window + site event rules before firing","sources":["https://yucatanmagazine.com/chichen-itza-equinox/","https://www.exoticca.com/us/blog/witnessing-the-2026-spring-equinox-chichen-itza-teotihuacan-and-beyond/","https://chichenitzamexico.org/entrance-fee/"]},"jewels":[{"name":"Dawn / 8:00 AM early entry to El Castillo","status":"future","tier":"comfort","bookable":"DMC early-entry tour + INAH/CULTUR entry","source":"https://chichenitzamexico.org/entrance-fee/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the ceremonial core empty and cool before the buses; the only way to photograph the Wonder without crowds or midday heat","si":"culture","blurb":"the ceremonial core empty and cool before the buses; the only way to photograph the Wonder without crowds or midday heat","when":"dry season Nov-Apr","commission":"Amstar/Olympus DMC + Viator affiliate (site fees non-commissionable)","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''amstar/olympus dmc + viator affiliate (s''","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Spring-equinox serpent-shadow (Kukulcán descending)","status":"future","tier":"comfort","bookable":"equinox early-entry tour + beds booked Jan-Feb","source":"https://yucatanmagazine.com/chichen-itza-equinox/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the once-a-year engineered light-and-shadow spectacle, 4:30–5:10 PM ~Mar 20–21; the event peak","si":"culture","blurb":"the once-a-year engineered light-and-shadow spectacle, 4:30–5:10 PM ~Mar 20–21; the event peak","when":"dry season Nov-Apr","commission":"DMC + affiliate; base beds via bedbank/consortia","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''dmc + affiliate; base beds via bedbank/c''","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate","consortia"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Evening Noches de Kukulcán light-and-sound show","status":"future","tier":"comfort","bookable":"evening ticket + guide (verify seasonal schedule)","source":"https://www.chichenitza.com/tickets","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"after-dark projection-mapping over the ruins, extends the day and the spend","si":"culture","blurb":"after-dark projection-mapping over the ruins, extends the day and the spend","when":"dry season Nov-Apr","commission":"DMC + affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Yaxunáh community-Maya alternative","status":"future","tier":"comfort","bookable":"private community tour (Amigo Tours / Marriott Bonvoy activities)","source":"https://yucatantoday.com/en/yaxunah-a-community-run-paradise/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a living Maya community + quiet archaeological zone just south of Chichén; the responsible, crowd-free counter to the Wonder","si":"culture","blurb":"a living Maya community + quiet archaeological zone just south of Chichén; the responsible, crowd-free counter to the Wonder","when":"dry season Nov-Apr","commission":"private-tour DMC + Viator affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''private-tour dmc + viator affiliate''","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cenote Ik Kil swim","status":"live","tier":"essential","bookable":"entry ~250 MXN + combo day tour","source":"https://cenotetickets.com/blog/en/cenote-ik-kil-entrance-fee-2025/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the iconic ~40 m emerald sinkhole 3 km from the ruins with vine curtains and waterfalls","si":"expedition","blurb":"the iconic ~40 m emerald sinkhole 3 km from the ruins with vine curtains and waterfalls","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate (entry non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","expedition"],"shelf_fit":{"culture":"evidenced","expedition":"primary","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Balankanché caves (guided grotto)","status":"live","tier":"essential","bookable":"entry + guided cave tour","source":"https://www.chichenitza.com/cenotes/ik-kil-cenote","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":">1 km underworld ritual cave with ancient Maya-Toltec offering chambers, a few km from the ruins — the archaeology-under-the-earth complement to the surface city","si":"expedition","blurb":">1 km underworld ritual cave with ancient Maya-Toltec offering chambers, a few km from the ruins — the archaeology-under-the-earth complement to the surface city","when":"dry season Nov-Apr","commission":"DMC + affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","expedition"],"shelf_fit":{"culture":"evidenced","expedition":"primary","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Hacienda Chichén stay + Yaxkin Spa","status":"future","tier":"premier","bookable":"FIT / consortia direct","source":"https://www.haciendachichen.com/","timing":"year-round","timing_type":"ALWAYS-ON","si":"wellness","when":"year-round","commission":"host/Virtuoso where property participates; commission on application","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["wellness"],"shelf_fit":{"culture":"destination","expedition":"destination","wellness":"primary"},"commission_lane":["consortia"],"commission_embedded":false,"commission_basis":"2026-10-05: Fora removed - excluded by David 2026-09-05; the remaining route kept","commission_was":"host/Fora-Virtuoso where property participates; commission on application"}],"faq":[{"q":"When is the equinox serpent-shadow and how do I see it?","a":"The spring equinox around March 20–21 is the peak, when seven triangles of light descend the north staircase of El Castillo between roughly 4:30 and 5:10 PM and Kukulcán appears to slither toward the stone serpent-head — the Maya engineered it more than a thousand years ago. It drew 8,400 people in 2026; the autumn equinox (~Sep 22–23) is the quieter alternative. Book beds and guided early entry in January–February.","source":"yucatanmagazine.com, 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"Can you still climb the pyramid at Chichén Itzá?","a":"No — climbing El Castillo has been banned since 2008 by INAH to protect the structure, and as of 2025 unauthorized climbing draws fines of roughly US$3,200–16,000. You photograph the Wonder from the plaza at the 8:00 AM opening, before the buses and the heat.","source":"chichenitza.com, 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"Can beginners and kids swim Cenote Ik Kil?","a":"Yes — it is a surface swim, not a dive. Ik Kil is a ~40 m-deep open sinkhole 3 km from the ruins with provided life jackets (mandatory posture for non-swimmers and children) and no lifeguard, so shower off sunscreen first and take the steep wet stairs carefully. Entry is 250 MXN.","source":"cenotetickets.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"Where do you actually stay at Chichén Itzá?","a":"On-site the market is thin but premium — two heritage hotels: Hacienda Chichén (a restored 16th-c. hacienda on a 200-ha private jungle reserve with the Yaxkin Maya-healing spa) and the adjacent Mayaland. Most travelers base at Valladolid (~40 min) or the Mérida hacienda circuit (~2 hr) and day-trip the ruins.","source":"haciendachichen.com, 2026-07-06","si_tag":"wellness","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for at Chichén Itzá?","a":"Extreme heat and sun, not crime. The ceremonial core is a large, open, shadeless site in intense Yucatán sun, and heat exhaustion is the #1 incident risk — enter at the 8:00 AM opening, carry 1.5–2 L of water per person, wear a sun hat and high SPF, and plan a midday exit. On equinox afternoons you stand in heat among thousands, so hydrate and hold position early.","source":"exoticca.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"How far is medical care from Chichén Itzá?","a":"Roughly 2 hours either direction — the zone is rural. The nearest full trauma care is Mérida (~2 hr west, Star Médica / Clínica de Mérida) or Cancún (~2 hr east, Hospiten / Amerimed), so carry travel-medical and evacuation insurance.","source":"chichenitzamexico.org, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Chichén Itzá 2026: Equinox Serpent Shadow, Ik Kil & Fees","meta_description":"Chichén Itzá is a New Wonder — see the spring-equinox serpent shadow (~Mar 20–21), swim Cenote Ik Kil and explore Balankanché caves. Fees (~697 MXN), hours, no-climb rule, safety.","slug":"chichen-itza-mexico","primary_keyword":"Chichén Itzá","long_tail":["Chichén Itzá spring equinox 2026 serpent shadow","Chichén Itzá entrance fee 2026","can you climb Chichén Itzá El Castillo","Cenote Ik Kil near Chichén Itzá","Balankanché caves","Hacienda Chichén heritage stay","Chichén Itzá day trip from Cancún Mérida"],"search_language":["en","es-MX"],"local_keywords":["Chichén Itzá equinoccio","serpiente de luz Kukulcán El Castillo","precio entrada Chichén Itzá 2026","no se puede subir El Castillo","Cenote Ik Kil Chichén Itzá","grutas de Balankanché","Chichén Itzá desde Cancún Mérida","Hacienda Chichén hospedaje"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"future"},{"si":"expedition","status":"live"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Hacienda Chichen Resort & Yaxkin Spa","tier":"premier-luxury boutique heritage (straight - extraordinary location/story, not 5-star palace)","why":"sleep at the foot of the Wonder; restored 16th-c. hacienda, 200-ha private jungle reserve, Maya-healing spa","earning":"FIT/consortia (Fora/Virtuoso where property participates), commission on application","mor":"host MoR on base-stay + private-tour side; site fees non-commissionable","source":"https://www.haciendachichen.com/"},{"name":"Chable Yucatan (Merida circuit, ~2 hr W) - nearest TRUE ultra","tier":"ultra-luxury (Leading Hotels of the World)","why":"200-yr San Antonio hacienda, 750 acres, spa beside a sacred cenote, ~30 min from MID; base for private-guided Chichen ultra day excursion","earning":"FIT/consortia (Virtuoso/Fora), commission on application","mor":"host MoR on stay + private tour","source":"https://www.lhw.com/hotel/Chable-Yucatan-Chochola-Merida-Mexico"}],"source_verified":"2026-07-06","hero":{"query":"Chichén Itzá, Mexico"},"geo":{"lat":20.6843,"lng":-88.5678},"orbit":[{"id":"celestun-mexico","jewels":6,"si":["expedition","tropical"]},{"id":"izamal-mexico","jewels":8,"si":["culture","romance","culinary"]},{"id":"merida-mexico","jewels":15,"si":["romance","expedition","culture","culinary"]},{"id":"rio-lagartos-mexico","jewels":6,"si":["expedition","tropical"]},{"id":"uxmal-mexico","jewels":11,"si":["culture","expedition","culinary"]},{"id":"valladolid-mexico","jewels":9,"si":["expedition","culture","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexic