  ('chiloe-island-chile', '10S', 'Chiloé Island & the Chilean Lake District', 'Chile', 'Stilt houses, wooden churches, fog', 'live', 'verified', 'mountainValley', 'Chile — Patagonia & The Lakes', '{"expedition","romance","culture"}', '{}', '{"essential","premier","luxury"}', null, null, '{"key_facts":null,"safety":{"emergency":"131","emergency_all":{"ambulance_samu":"131","police_carabineros":"133","fire_bomberos":"132"},"advisory_why":"crime + civil unrest concentrated in central Santiago; Araucania/Biobio state-of-emergency is mainland, well north of Chiloe","advisory_source":"https://www.gov.uk/foreign-travel-advice/chile","air_access_verified":true,"maritime_headline":"sea + weather is the real risk: cold-water/swell on Punihuil boats (life vests mandatory), rough ferry crossings, exposed sea-cliff hikes, cold/rain exposure year-round","wet_weather_driving":"self-drive island; frequent rain/fog, narrow rural roads, ferry timing — drive to conditions","water":"Castro/Ancud tap generally potable; rural/small-island varies — note, not guaranteed","evac_chain":"Castro/Ancud clinic -> Puerto Montt regional hospital (via ferry/road or air) -> Santiago; travel+medical insurance strongly indicated","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/chile","read":"2026-09-01T16:18:21Z","page_updated":"2026-08-18T23:18:12+01:00","source_country":"chile","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"Dec-Mar (austral summer — drier; penguin boats Sep-Mar, most penguins Dec-Jan)","shoulder":["Oct-Nov","Apr"],"wet_moody_offseason":"May-Sep (penguin boats stopped; fog/rain — a genuine draw for some; fill-the-beds)","booking_window":"luxe lodge + peak palafito-boutique months ahead; day-tours/penguin boats last-minute walk-up","inflection":"penguin season opens (Sep) + Southern-summer bookings firm for Dec-Mar","fire_date":"mid-to-late August (c